import java.util.*;

public class Main {
    // Try every pair: O(N^2) time, O(1) space.
    static int[] brute(int[] a, int target) {
        int steps = 0;
        for (int i = 0; i < a.length; i++)
            for (int j = i + 1; j < a.length; j++) {
                steps++;
                if (a[i] + a[j] == target) return new int[]{i, j, steps};
            }
        return new int[]{-1, -1, steps};
    }

    // Remember earlier values in a hash map: O(N) time, O(N) space.
    static int[] fast(int[] a, int target) {
        Map<Integer, Integer> seen = new HashMap<>();   // value -> index
        int steps = 0;
        for (int j = 0; j < a.length; j++) {
            steps++;
            Integer i = seen.get(target - a[j]);        // was the partner seen earlier?
            if (i != null) return new int[]{i, j, steps};
            seen.put(a[j], j);
        }
        return new int[]{-1, -1, steps};
    }

    public static void main(String[] args) {
        int[] a = {2, 7, 11, 15, 1, 8};
        int target = 19;
        System.out.println("Input: " + Arrays.toString(a) + " target " + target);
        int[] r = brute(a, target);
        System.out.println("Brute force: indexes " + r[0] + " " + r[1] + " after " + r[2] + " steps");
        r = fast(a, target);
        System.out.println("Hash map: indexes " + r[0] + " " + r[1] + " after " + r[2] + " steps");
    }
}

