// Start with the brute force, then remove its repeated work.
function brute(a, target) {
  let steps = 0;
  for (let i = 0; i < a.length; i++) {
    for (let j = i + 1; j < a.length; j++) {   // try every pair: O(N^2) time, O(1) space
      steps++;
      if (a[i] + a[j] === target) return [i, j, steps];
    }
  }
  return [-1, -1, steps];
}

function fast(a, target) {
  const seen = new Map();                      // value -> index of values already passed
  let steps = 0;
  for (let j = 0; j < a.length; j++) {
    steps++;
    if (seen.has(target - a[j])) {             // was the partner seen earlier? O(1) lookup
      return [seen.get(target - a[j]), j, steps];
    }
    seen.set(a[j], j);
  }
  return [-1, -1, steps];                      // O(N) time, O(N) space
}

