using namespace std;

// Try every pair: O(N^2) time, O(1) space.
array<int, 3> brute(const vector<int>& a, int target) {
    int steps = 0;
    for (int i = 0; i < (int)a.size(); i++)
        for (int j = i + 1; j < (int)a.size(); j++) {
            steps++;
            if (a[i] + a[j] == target) return {i, j, steps};
        }
    return {-1, -1, steps};
}

// Remember earlier values in a hash map: O(N) time, O(N) space.
array<int, 3> fast(const vector<int>& a, int target) {
    unordered_map<int, int> seen;                 // value -> index
    int steps = 0;
    for (int j = 0; j < (int)a.size(); j++) {
        steps++;
        auto it = seen.find(target - a[j]);       // was the partner seen earlier?
        if (it != seen.end()) return {it->second, j, steps};
        seen[a[j]] = j;
    }
    return {-1, -1, steps};
}

