import java.util.*;

public class Main {
    // Every subarray a[i..j]: O(N^2) time, O(1) space.
    static int countBrute(int[] a, int k) {
        int count = 0;
        for (int i = 0; i < a.length; i++) {
            int total = 0;
            for (int j = i; j < a.length; j++) {
                total += a[j];
                if (total == k) count++;
            }
        }
        return count;
    }

    // Prefix sums + hash map: O(N) time, O(N) space. Works with negatives.
    static int countPrefix(int[] a, int k) {
        Map<Integer, Integer> seen = new HashMap<>();   // prefix sum -> times it appeared
        seen.put(0, 1);
        int run = 0, count = 0;
        for (int x : a) {
            run += x;                                   // prefix sum ending here
            count += seen.getOrDefault(run - k, 0);     // earlier prefixes that leave exactly k
            seen.merge(run, 1, Integer::sum);
        }
        return count;
    }

    public static void main(String[] args) {
        int[] a = {3, 4, -7, 1, 3, 3, 1, -4};
        int k = 7;
        System.out.println("Input: " + Arrays.toString(a) + " k = " + k);
        System.out.println("Brute force count: " + countBrute(a, k));
        System.out.println("Prefix sum + hash map count: " + countPrefix(a, k));
    }
}

