// With negative numbers a sliding window does not know which pointer to move,
// so we count with prefix sums and a hash map instead.
function countBrute(a, k) {
  let count = 0;
  for (let i = 0; i < a.length; i++) {
    let total = 0;
    for (let j = i; j < a.length; j++) {   // every subarray a[i..j]: O(N^2) time
      total += a[j];
      if (total === k) count++;
    }
  }
  return count;
}

function countPrefix(a, k) {
  const seen = new Map([[0, 1]]);          // prefix sum -> how many times it appeared
  let run = 0, count = 0;
  for (const x of a) {
    run += x;                              // prefix sum ending here
    count += seen.get(run - k) || 0;       // earlier prefixes that leave exactly k
    seen.set(run, (seen.get(run) || 0) + 1);
  }
  return count;                            // O(N) time, O(N) space
}

