class Program {
    // Every subarray a[i..j]: O(N^2) time, O(1) space.
    static int CountBrute(int[] a, int k) {
        int count = 0;
        for (int i = 0; i < a.Length; i++) {
            int total = 0;
            for (int j = i; j < a.Length; j++) {
                total += a[j];
                if (total == k) count++;
            }
        }
        return count;
    }

    // Prefix sums + hash map: O(N) time, O(N) space. Works with negatives.
    static int CountPrefix(int[] a, int k) {
        Dictionary<int, int> seen = new Dictionary<int, int>();   // prefix sum -> times it appeared
        seen[0] = 1;
        int run = 0, count = 0;
        foreach (int x in a) {
            run += x;                                             // prefix sum ending here
            int times;
            if (seen.TryGetValue(run - k, out times)) count += times;   // earlier prefixes that leave k
