import java.util.*;

public class Main {
    // Min-heap of the k largest values: O(N log k) time, O(k) space.
    static int kthHeap(int[] a, int k) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int x : a) {
            heap.add(x);
            if (heap.size() > k) heap.poll();   // drop the smallest, it cannot be the answer
        }
        return heap.peek();
    }

    // Quickselect: average O(N) time, worst O(N^2); reorders the data.
    static int kthQuickselect(int[] src, int k) {
        int[] a = src.clone();                  // work on a copy
        int lo = 0, hi = a.length - 1, want = a.length - k;
        while (true) {
            int pivot = a[hi], p = lo;          // last element as pivot (random in real code)
            for (int i = lo; i < hi; i++)
                if (a[i] < pivot) { int t = a[i]; a[i] = a[p]; a[p] = t; p++; }
            int t = a[p]; a[p] = a[hi]; a[hi] = t;   // pivot is now at its sorted position p
            if (p == want) return a[p];
            if (p < want) lo = p + 1;           // keep only the side that holds the answer
            else hi = p - 1;
        }
    }

    public static void main(String[] args) {
        int[] a = {3, 2, 1, 5, 6, 4};
        int k = 2;
        System.out.println("Input: " + Arrays.toString(a) + " k = " + k);
        System.out.println("Heap of size k: " + kthHeap(a, k));
        System.out.println("Quickselect: " + kthQuickselect(a, k));
    }
}

