        pivot, p = a[hi], lo           # last element as pivot (use a random one in real code)
        for i in range(lo, hi):
            if a[i] < pivot:
                a[i], a[p] = a[p], a[i]
                p += 1
        a[p], a[hi] = a[hi], a[p]      # pivot is now at its sorted position p
        if p == want:
            return a[p]
        if p < want:
            lo = p + 1                 # keep only the side that holds the answer
        else:
            hi = p - 1                 # average O(N) time, worst O(N^2)

