// JavaScript has no built-in heap, so here is a small min-heap on an array.
function heapPush(h, x) {
  h.push(x);
  let i = h.length - 1;
  while (i > 0) {                               // sift up while smaller than the parent
    const p = (i - 1) >> 1;
    if (h[p] <= h[i]) break;
    [h[p], h[i]] = [h[i], h[p]];
    i = p;
  }
}
function heapPop(h) {
  const top = h[0], last = h.pop();
  if (h.length > 0) {
    h[0] = last;
    let i = 0;
    while (true) {                              // sift down to the smaller child
      let s = i;
      const l = 2 * i + 1, r = l + 1;
      if (l < h.length && h[l] < h[s]) s = l;
      if (r < h.length && h[r] < h[s]) s = r;
      if (s === i) break;
      [h[s], h[i]] = [h[i], h[s]];
      i = s;
    }
  }
  return top;
}

function kthHeap(a, k) {
  const heap = [];                              // holds the k largest values so far
  for (const x of a) {
    heapPush(heap, x);
    if (heap.length > k) heapPop(heap);         // drop the smallest
  }
  return heap[0];                               // O(N log k) time, O(k) space
}

function kthQuickselect(src, k) {
  const a = src.slice();                        // work on a copy
  let lo = 0, hi = a.length - 1;
  const want = a.length - k;
  while (true) {
    const pivot = a[hi];                        // last element as pivot (random in real code)
    let p = lo;
    for (let i = lo; i < hi; i++) {
      if (a[i] < pivot) { [a[i], a[p]] = [a[p], a[i]]; p++; }
    }
    [a[p], a[hi]] = [a[hi], a[p]];              // pivot is now at its sorted position p
    if (p === want) return a[p];
    if (p < want) lo = p + 1; else hi = p - 1;  // average O(N) time, worst O(N^2)
  }
}

