// Min-heap of the k largest values: O(N log k) time, O(k) space.
int kthHeap(const vector<int>& a, int k) {
    priority_queue<int, vector<int>, greater<int>> heap;
    for (int x : a) {
        heap.push(x);
        if ((int)heap.size() > k) heap.pop();   // drop the smallest, it cannot be the answer
    }
    return heap.top();
}

// Quickselect: average O(N) time, worst O(N^2); reorders the data.
int kthQuickselect(vector<int> a, int k) {      // passed by value, so this is a copy
    int lo = 0, hi = (int)a.size() - 1, want = (int)a.size() - k;
    while (true) {
        int pivot = a[hi], p = lo;              // last element as pivot (random in real code)
        for (int i = lo; i < hi; i++)
            if (a[i] < pivot) swap(a[i], a[p++]);
        swap(a[p], a[hi]);                      // pivot is now at its sorted position p
        if (p == want) return a[p];
        if (p < want) lo = p + 1;               // keep only the side that holds the answer
        else hi = p - 1;
    }
}

