using System;
using System.Collections.Generic;

class Program {
    // A small min-heap on a List<int> (kept simple so it compiles everywhere).
    static void Push(List<int> h, int x) {
        h.Add(x);
        int i = h.Count - 1;
        while (i > 0) {                              // sift up while smaller than the parent
            int p = (i - 1) / 2;
            if (h[p] <= h[i]) break;
            int t = h[p]; h[p] = h[i]; h[i] = t;
            i = p;
        }
    }
    static void Pop(List<int> h) {
        h[0] = h[h.Count - 1];
        h.RemoveAt(h.Count - 1);
        int i = 0;
        while (true) {                               // sift down to the smaller child
            int s = i, l = 2 * i + 1, r = l + 1;
            if (l < h.Count && h[l] < h[s]) s = l;
            if (r < h.Count && h[r] < h[s]) s = r;
            if (s == i) break;
            int t = h[s]; h[s] = h[i]; h[i] = t;
            i = s;
        }
    }
    // Keep the k largest values: O(N log k) time, O(k) space.
    static int KthHeap(int[] a, int k) {
        List<int> heap = new List<int>();
        foreach (int x in a) {
            Push(heap, x);
            if (heap.Count > k) Pop(heap);           // drop the smallest
        }
        return heap[0];
    }
    // Quickselect: average O(N) time, worst O(N^2); reorders the data.
    static int KthQuickselect(int[] src, int k) {
        int[] a = (int[])src.Clone();                // work on a copy
        int lo = 0, hi = a.Length - 1, want = a.Length - k;
        while (true) {
            int pivot = a[hi], p = lo, t;            // last element as pivot (random in real code)
            for (int i = lo; i < hi; i++)
                if (a[i] < pivot) { t = a[i]; a[i] = a[p]; a[p] = t; p++; }
            t = a[p]; a[p] = a[hi]; a[hi] = t;       // pivot is now at its sorted position p
            if (p == want) return a[p];
            if (p < want) lo = p + 1; else hi = p - 1;
        }
    }
    static void Main() {
        int[] a = { 3, 2, 1, 5, 6, 4 };
        int k = 2;
        Console.WriteLine("Input: [" + string.Join(", ", a) + "] k = " + k);
        Console.WriteLine("Heap of size k: " + KthHeap(a, k));
        Console.WriteLine("Quickselect: " + KthQuickselect(a, k));
    }
}

