import java.util.*;

public class Main {
    // Slow but obviously correct: grow from every start until a letter repeats. O(N^2).
    static int longestBrute(String s) {
        int best = 0;
        for (int i = 0; i < s.length(); i++) {
            Set<Character> seen = new HashSet<>();
            for (int j = i; j < s.length(); j++) {
                if (!seen.add(s.charAt(j))) break;   // add returns false on a repeat
            }
            best = Math.max(best, seen.size());
        }
        return best;
    }

    // Sliding window: O(N) time, O(alphabet) space.
    static int longestWindow(String s) {
        Map<Character, Integer> last = new HashMap<>();   // letter -> index last seen
        int left = 0, best = 0;
        for (int right = 0; right < s.length(); right++) {
            char ch = s.charAt(right);
            if (last.containsKey(ch) && last.get(ch) >= left)
                left = last.get(ch) + 1;                  // jump left past the earlier copy
            last.put(ch, right);
            best = Math.max(best, right - left + 1);
        }
        return best;
    }

    public static void main(String[] args) {
        String[] tests = {"abcabcbb", "bbbbb", "pwwkew", "", "abba"};
        for (String s : tests) {
            int b = longestBrute(s), w = longestWindow(s);
            System.out.println("\"" + s + "\" brute = " + b + " window = " + w + " " + (b == w ? "OK" : "MISMATCH"));
        }
    }
}

