import java.util.*;

public class Main {
    static int shortest(String[] grid, int sr, int sc, int tr, int tc) {
        int rows = grid.length, cols = grid[0].length();
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) Arrays.fill(row, -1);     // -1 means "not visited yet"
        dist[sr][sc] = 0;
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{sr, sc});
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();                    // cells leave in order of distance
            int r = cur[0], c = cur[1];
            if (r == tr && c == tc) return dist[r][c];   // the first visit is the shortest
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                if (grid[nr].charAt(nc) == '#' || dist[nr][nc] != -1) continue;
                dist[nr][nc] = dist[r][c] + 1;           // mark when adding to the queue
                queue.add(new int[]{nr, nc});
            }
        }
        return -1;                                       // target cannot be reached
    }

    public static void main(String[] args) {
        String[] grid = {"..#.", "..#.", "....", "#..."};
        System.out.println("Grid ('#' is a wall):");
        for (String row : grid) System.out.println(row);
        System.out.println("Minimum steps from (0,0) to (0,3): " + shortest(grid, 0, 0, 0, 3));
        // Time O(rows * cols), space O(rows * cols).
    }
}

