class Program {
    static int Shortest(string[] grid, int sr, int sc, int tr, int tc) {
        int rows = grid.Length, cols = grid[0].Length;
        int[,] dist = new int[rows, cols];
        for (int i = 0; i < rows; i++)
            for (int j = 0; j < cols; j++) dist[i, j] = -1;   // -1 means "not visited yet"
        dist[sr, sc] = 0;
        Queue<int[]> queue = new Queue<int[]>();
        queue.Enqueue(new int[] { sr, sc });
        int[] dr = { 1, -1, 0, 0 }, dc = { 0, 0, 1, -1 };
        while (queue.Count > 0) {
            int[] cur = queue.Dequeue();                      // cells leave in order of distance
            int r = cur[0], c = cur[1];
            if (r == tr && c == tc) return dist[r, c];        // the first visit is the shortest
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                if (grid[nr][nc] == '#' || dist[nr, nc] != -1) continue;
                dist[nr, nc] = dist[r, c] + 1;                // mark when adding to the queue
                queue.Enqueue(new int[] { nr, nc });
            }
        }
        return -1;                                            // target cannot be reached
