import java.util.*;

public class Main {
    public static void main(String[] args) {
        // State: dp[c] = best total value using the items seen so far with capacity c.
        int[] weights = {1, 3, 4, 5};
        int[] values = {1, 4, 5, 7};
        int cap = 7;
        System.out.println("Weights: " + Arrays.toString(weights));
        System.out.println("Values: " + Arrays.toString(values));
        System.out.println("Capacity: " + cap);

        int[] dp = new int[cap + 1];          // no items yet: value 0 for every capacity
        for (int i = 0; i < weights.length; i++) {
            int w = weights[i], v = values[i];
            // Go from high capacity to low so dp[c - w] still belongs to the previous item row.
            for (int c = cap; c >= w; c--)
                dp[c] = Math.max(dp[c], dp[c - w] + v);   // skip the item, or take it
            System.out.println("after item (w=" + w + ", v=" + v + "): " + Arrays.toString(dp));
        }
        System.out.println("Best value: " + dp[cap]);
        // Time O(N * capacity), space O(capacity).
    }
}

