import java.util.*;

public class Main {
    // Pick meetings greedily after sorting by one field: 0 = start time, 1 = end time.
    static int pick(int[][] intervals, int key) {
        int[][] order = intervals.clone();
        Arrays.sort(order, (x, y) -> Integer.compare(x[key], y[key]));
        int count = 0;
        int freeFrom = Integer.MIN_VALUE;          // time at which the room becomes free
        for (int[] iv : order) {
            if (iv[0] >= freeFrom) {               // does not overlap the last meeting we took
                count++;
                freeFrom = iv[1];
            }
        }
        return count;                              // O(N log N) time for the sort, O(N) space
