import java.util.*;

public class Main {
    // BFS on an open n x n grid from (0,0) to (n-1,n-1). Returns {steps, queue pushes}.
    static int[] bfs(int n, boolean markOnPush) {
        boolean[][] visited = new boolean[n][n];
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{0, 0, 0});
        int pushes = 1, answer = -1;
        if (markOnPush) visited[0][0] = true;
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0], c = cur[1], d = cur[2];
            if (!markOnPush) {
                if (visited[r][c]) continue;       // a duplicate entry: wasted work
                visited[r][c] = true;              // the subtle bug: marking this late
            }
            if (r == n - 1 && c == n - 1 && answer == -1) answer = d;
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k], nc = c + dc[k];
                if (nr < 0 || nr >= n || nc < 0 || nc >= n || visited[nr][nc]) continue;
                if (markOnPush) visited[nr][nc] = true;   // correct: each cell enters once
                queue.add(new int[]{nr, nc, d + 1});
                pushes++;
            }
        }
        return new int[]{answer, pushes};
    }

