from collections import deque

# BFS on an open n x n grid from (0,0) to (n-1,n-1). Returns (steps, queue pushes).
def bfs(n, mark_on_push):
    visited = [[False] * n for _ in range(n)]
    queue = deque([(0, 0, 0)])
    pushes = 1
    answer = -1
    if mark_on_push:
        visited[0][0] = True
    while queue:
        r, c, d = queue.popleft()
        if not mark_on_push:
            if visited[r][c]:
                continue                  # a duplicate entry: wasted work
            visited[r][c] = True          # the subtle bug: marking this late
        if r == n - 1 and c == n - 1 and answer == -1:
            answer = d
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and not visited[nr][nc]:
                if mark_on_push:
                    visited[nr][nc] = True   # correct: each cell enters the queue once
                queue.append((nr, nc, d + 1))
                pushes += 1
    return answer, pushes

