import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Each chunk stands for a sorted file on disk. We only ever hold one value per chunk.
        int[][] chunks = {{1, 4, 9}, {2, 3, 10}, {5, 6, 7, 8}};
        StringBuilder sb = new StringBuilder("Sorted chunks:");
        for (int[] c : chunks) sb.append(" ").append(Arrays.toString(c));
        System.out.println(sb);

        // Heap entries: {value, chunk number, position in chunk}, smallest value on top.
        PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
        for (int i = 0; i < chunks.length; i++) heap.add(new int[]{chunks[i][0], i, 0});

        List<Integer> merged = new ArrayList<>();
        while (!heap.isEmpty()) {
            int[] top = heap.poll();               // smallest value among all chunk fronts
            merged.add(top[0]);                    // in real life: write it to the output file
            int i = top[1], pos = top[2];
            if (pos + 1 < chunks[i].length)        // refill from the same chunk
                heap.add(new int[]{chunks[i][pos + 1], i, pos + 1});
        }
        System.out.println("Merged: " + merged);
        // Time O(N log k) for N values in k chunks, memory O(k) besides the output.
    }
}

