// JavaScript has no built-in heap: a small min-heap of [value, chunk, position] entries.
function heapPush(h, x) {
  h.push(x);
  let i = h.length - 1;
  while (i > 0) {                               // sift up while smaller than the parent
    const p = (i - 1) >> 1;
    if (h[p][0] <= h[i][0]) break;
    [h[p], h[i]] = [h[i], h[p]];
    i = p;
  }
}
function heapPop(h) {
  const top = h[0], last = h.pop();
  if (h.length > 0) {
    h[0] = last;
    let i = 0;
    while (true) {                              // sift down to the smaller child
      let s = i;
      const l = 2 * i + 1, r = l + 1;
      if (l < h.length && h[l][0] < h[s][0]) s = l;
      if (r < h.length && h[r][0] < h[s][0]) s = r;
      if (s === i) break;
      [h[s], h[i]] = [h[i], h[s]];
      i = s;
    }
  }
  return top;
}

