const merged = [];
while (heap.length > 0) {
  const [value, i, pos] = heapPop(heap);        // smallest value among all chunk fronts
  merged.push(value);                           // in real life: write it to the output file
  if (pos + 1 < chunks[i].length) {             // refill from the same chunk
    heapPush(heap, [chunks[i][pos + 1], i, pos + 1]);
