using System;
using System.Collections.Generic;

class Program {
    static void Main() {
        // Each chunk stands for a sorted file on disk. We only ever hold one value per chunk.
        int[][] chunks = {
            new int[] { 1, 4, 9 }, new int[] { 2, 3, 10 }, new int[] { 5, 6, 7, 8 }
        };
        string line = "Sorted chunks:";
        foreach (int[] c in chunks) line += " [" + string.Join(", ", c) + "]";
        Console.WriteLine(line);

        // A sorted set of (value, chunk number) works as the heap: Min is the smallest front.
        // The chunk number makes every entry different, so equal values are not lost.
        SortedSet<Tuple<int, int>> heap = new SortedSet<Tuple<int, int>>();
        int[] pos = new int[chunks.Length];        // next unread position in each chunk
        for (int i = 0; i < chunks.Length; i++) heap.Add(Tuple.Create(chunks[i][0], i));

        List<int> merged = new List<int>();
        while (heap.Count > 0) {
            Tuple<int, int> top = heap.Min;        // smallest value among all chunk fronts
            heap.Remove(top);
            merged.Add(top.Item1);                 // in real life: write it to the output file
            int c = top.Item2;
            pos[c]++;
            if (pos[c] < chunks[c].Length)         // refill from the same chunk
                heap.Add(Tuple.Create(chunks[c][pos[c]], c));
        }
        Console.WriteLine("Merged: [" + string.Join(", ", merged) + "]");
        // Time O(N log k) for N values in k chunks, memory O(k) besides the output.
    }
}
